21	import {parsePercent} from '../../util/number';
22	import PieSeriesModel, { PieSeriesOption, PieDataItemOption } from './PieSeries';
23	import { VectorArray } from 'zrender/src/core/vector';
24	import { HorizontalAlign, ZRTextAlign } from '../../util/types';
25	import { Sector, Polyline, Point } from '../../util/graphic';
26	import ZRText from 'zrender/src/graphic/Text';
