341	export default function pieLabelLayout(
342	    seriesModel: PieSeriesModel
343	) {
344	    const data = seriesModel.getData();
345	    const labelLayoutList: LabelLayout[] = [];
346	    let cx;
347	    let cy;
348	    let hasLabelRotate = false;
349	    const minShowLabelRadian = (seriesModel.get('minShowLabelAngle') || 0) * RADIAN;
350	
351	    const viewRect = data.getLayout('viewRect') as RectLike;
352	    const r = data.getLayout('r') as number;
353	    const viewWidth = viewRect.width;
354	    const viewLeft = viewRect.x;
355	    const viewTop = viewRect.y;
356	    const viewHeight = viewRect.height;
357	
358	    function setNotShow(el: {ignore: boolean}) {
359	        el.ignore = true;
360	    }
361	
362	    function isLabelShown(label: ZRText) {
363	        if (!label.ignore) {
364	            return true;
365	        }
366	        for (const key in label.states) {
367	            if (label.states[key].ignore === false) {
368	                return true;
369	            }
370	        }
371	        return false;
372	    }
373	
374	    data.each(function (idx) {
375	        const sector = data.getItemGraphicEl(idx) as Sector;
376	        const sectorShape = sector.shape;
377	        const label = sector.getTextContent();
378	        const labelLine = sector.getTextGuideLine();
379	
380	        const itemModel = data.getItemModel<PieDataItemOption>(idx);
381	        const labelModel = itemModel.getModel('label');
382	        // Use position in normal or emphasis
383	        const labelPosition = labelModel.get('position') || itemModel.get(['emphasis', 'label', 'position']);
384	        const labelDistance = labelModel.get('distanceToLabelLine');
385	        const labelAlignTo = labelModel.get('alignTo');
386	        const edgeDistance = parsePercent(labelModel.get('edgeDistance'), viewWidth);
387	        const bleedMargin = labelModel.get('bleedMargin');
388	
389	        const labelLineModel = itemModel.getModel('labelLine');
390	        let labelLineLen = labelLineModel.get('length');
391	        labelLineLen = parsePercent(labelLineLen, viewWidth);
392	        let labelLineLen2 = labelLineModel.get('length2');
393	        labelLineLen2 = parsePercent(labelLineLen2, viewWidth);
394	
395	        if (Math.abs(sectorShape.endAngle - sectorShape.startAngle) < minShowLabelRadian) {
396	            each(label.states, setNotShow);
397	            label.ignore = true;
398	            if (labelLine) {
399	                each(labelLine.states, setNotShow);
400	                labelLine.ignore = true;
401	            }
402	            return;
403	        }
404	
405	        if (!isLabelShown(label)) {
406	            return;
407	        }
408	
409	        const midAngle = (sectorShape.startAngle + sectorShape.endAngle) / 2;
410	        const nx = Math.cos(midAngle);
411	        const ny = Math.sin(midAngle);
412	
413	        let textX;
414	        let textY;
415	        let linePoints;
416	        let textAlign: ZRTextAlign;
417	
418	        cx = sectorShape.cx;
419	        cy = sectorShape.cy;
420	
421	
422	        const isLabelInside = labelPosition === 'inside' || labelPosition === 'inner';
423	        if (labelPosition === 'center') {
424	            textX = sectorShape.cx;
425	            textY = sectorShape.cy;
426	            textAlign = 'center';
427	        }
428	        else {
429	            const x1 = (isLabelInside ? (sectorShape.r + sectorShape.r0) / 2 * nx : sectorShape.r * nx) + cx;
430	            const y1 = (isLabelInside ? (sectorShape.r + sectorShape.r0) / 2 * ny : sectorShape.r * ny) + cy;
431	
432	            textX = x1 + nx * 3;
433	            textY = y1 + ny * 3;
434	
435	            if (!isLabelInside) {
436	                // For roseType
437	                const x2 = x1 + nx * (labelLineLen + r - sectorShape.r);
438	                const y2 = y1 + ny * (labelLineLen + r - sectorShape.r);
439	                const x3 = x2 + ((nx < 0 ? -1 : 1) * labelLineLen2);
440	                const y3 = y2;
441	
442	                if (labelAlignTo === 'edge') {
443	                    // Adjust textX because text align of edge is opposite
444	                    textX = nx < 0
445	                        ? viewLeft + edgeDistance
446	                        : viewLeft + viewWidth - edgeDistance;
447	                }
448	                else {
449	                    textX = x3 + (nx < 0 ? -labelDistance : labelDistance);
450	                }
451	                textY = y3;
452	                linePoints = [[x1, y1], [x2, y2], [x3, y3]];
453	            }
454	
455	            textAlign = isLabelInside
456	                ? 'center'
457	                : (labelAlignTo === 'edge'
458	                    ? (nx > 0 ? 'right' : 'left')
459	                    : (nx > 0 ? 'left' : 'right'));
460	        }
461	
462	        const PI = Math.PI;
463	        let labelRotate = 0;
464	        const rotate = labelModel.get('rotate');
465	        if (isNumber(rotate)) {
466	            labelRotate = rotate * (PI / 180);
467	        }
468	        else if (labelPosition === 'center') {
469	            labelRotate = 0;
470	        }
471	        else if (rotate === 'radial' || rotate === true) {
472	            const radialAngle = nx < 0 ? -midAngle + PI : -midAngle;
473	            labelRotate = radialAngle;
474	        }
475	        else if (rotate === 'tangential'
476	            && labelPosition !== 'outside' && labelPosition !== 'outer'
477	        ) {
478	            let rad = Math.atan2(nx, ny);
479	            if (rad < 0) {
480	                rad = PI * 2 + rad;
481	            }
482	            const isDown = ny > 0;
483	            if (isDown) {
484	                rad = PI + rad;
485	            }
486	            labelRotate = rad - PI;
487	        }
488	
489	        hasLabelRotate = !!labelRotate;
490	
491	        label.x = textX;
492	        label.y = textY;
493	        label.rotation = labelRotate;
494	
495	        label.setStyle({
496	            verticalAlign: 'middle'
497	        });
498	
499	        // Not sectorShape the inside label
500	        if (!isLabelInside) {
501	            const textRect = label.getBoundingRect().clone();
502	            textRect.applyTransform(label.getComputedTransform());
503	            // Text has a default 1px stroke. Exclude this.
504	            const margin = (label.style.margin || 0) + 2.1;
505	            textRect.y -= margin / 2;
506	            textRect.height += margin;
507	
508	            labelLayoutList.push({
509	                label,
510	                labelLine,
511	                position: labelPosition,
512	                len: labelLineLen,
513	                len2: labelLineLen2,
514	                minTurnAngle: labelLineModel.get('minTurnAngle'),
515	                maxSurfaceAngle: labelLineModel.get('maxSurfaceAngle'),
516	                surfaceNormal: new Point(nx, ny),
517	                linePoints: linePoints,
518	                textAlign: textAlign,
519	                labelDistance: labelDistance,
520	                labelAlignTo: labelAlignTo,
521	                edgeDistance: edgeDistance,
522	                bleedMargin: bleedMargin,
523	                rect: textRect,
524	                unconstrainedWidth: textRect.width,
525	                labelStyleWidth: label.style.width
526	            });
527	        }
528	        else {
529	            label.setStyle({
530	                align: textAlign
531	            });
532	            const selectState = label.states.select;
533	            if (selectState) {
534	                selectState.x += label.x;
535	                selectState.y += label.y;
536	            }
537	        }
538	        sector.setTextConfig({
539	            inside: isLabelInside
540	        });
541	    });
542	
543	    if (!hasLabelRotate && seriesModel.get('avoidLabelOverlap')) {
544	        avoidOverlap(labelLayoutList, cx, cy, r, viewWidth, viewHeight, viewLeft, viewTop);
545	    }
546	
547	    for (let i = 0; i < labelLayoutList.length; i++) {
548	        const layout = labelLayoutList[i];
549	        const label = layout.label;
550	        const labelLine = layout.labelLine;
551	        const notShowLabel = isNaN(label.x) || isNaN(label.y);
552	        if (label) {
553	            label.setStyle({
554	                align: layout.textAlign
555	            });
556	            if (notShowLabel) {
557	                each(label.states, setNotShow);
558	                label.ignore = true;
559	            }
560	            const selectState = label.states.select;
561	            if (selectState) {
562	                selectState.x += label.x;
563	                selectState.y += label.y;
564	            }
565	        }
566	        if (labelLine) {
567	            const linePoints = layout.linePoints;
568	            if (notShowLabel || !linePoints) {
569	                each(labelLine.states, setNotShow);
570	                labelLine.ignore = true;
571	            }
572	            else {
573	                limitTurnAngle(linePoints, layout.minTurnAngle);
574	                limitSurfaceAngle(linePoints, layout.surfaceNormal, layout.maxSurfaceAngle);
575	
576	                labelLine.setShape({ points: linePoints });
577	
578	                // Set the anchor to the midpoint of sector
579	                label.__hostTarget.textGuideLineConfig = {
580	                    anchor: new Point(linePoints[0][0], linePoints[0][1])
581	                };
582	            }
583	        }
584	    }
585	}

