20	import ZRText from 'zrender/src/graphic/Text';
21	import { LabelLayoutOption } from '../util/types';
22	import { BoundingRect, OrientedBoundingRect, Polyline } from '../util/graphic';
23	import type Element from 'zrender/src/Element';
