25	interface LabelLayoutListPrepareInput {
26	    label: ZRText
27	    labelLine?: Polyline
28	    computedLayoutOption?: LabelLayoutOption
29	    priority: number
30	    defaultAttr: {
31	        ignore: boolean
32	        labelGuideIgnore?: boolean
33	    }
34	}
35	
36	export interface LabelLayoutInfo {
37	    label: ZRText
38	    labelLine: Polyline
39	    priority: number
40	    rect: BoundingRect // Global rect
41	    localRect: BoundingRect
42	    obb?: OrientedBoundingRect  // Only available when axisAligned is true
43	    axisAligned: boolean
44	    layoutOption: LabelLayoutOption
45	    defaultAttr: {
46	        ignore: boolean
47	        labelGuideIgnore?: boolean
48	    }
49	    transform: number[]
50	}
51	
52	export function prepareLayoutList(input: LabelLayoutListPrepareInput[]): LabelLayoutInfo[] {
53	    const list: LabelLayoutInfo[] = [];
54	
55	    for (let i = 0; i < input.length; i++) {
56	        const rawItem = input[i];
57	        if (rawItem.defaultAttr.ignore) {
58	            continue;
59	        }
60	
61	        const label = rawItem.label;
62	        const transform = label.getComputedTransform();
63	        // NOTE: Get bounding rect after getComputedTransform, or label may not been updated by the host el.
64	        const localRect = label.getBoundingRect();
65	        const isAxisAligned = !transform || (transform[1] < 1e-5 && transform[2] < 1e-5);
66	
67	        const minMargin = label.style.margin || 0;
68	        const globalRect = localRect.clone();
69	        globalRect.applyTransform(transform);
70	        globalRect.x -= minMargin / 2;
71	        globalRect.y -= minMargin / 2;
72	        globalRect.width += minMargin;
73	        globalRect.height += minMargin;
74	
