93	function shiftLayout(
94	    list: Pick<LabelLayoutInfo, 'rect' | 'label'>[],
95	    xyDim: 'x' | 'y',
96	    sizeDim: 'width' | 'height',
97	    minBound: number,
98	    maxBound: number,
99	    balanceShift: boolean
100	) {
101	    const len = list.length;
102	
103	    if (len < 2) {
104	        return;
105	    }
106	
107	    list.sort(function (a, b) {
108	        return a.rect[xyDim] - b.rect[xyDim];
109	    });
110	
111	    let lastPos = 0;
112	    let delta;
113	    let adjusted = false;
114	
115	    const shifts = [];
116	    let totalShifts = 0;
117	    for (let i = 0; i < len; i++) {
118	        const item = list[i];
119	        const rect = item.rect;
120	        delta = rect[xyDim] - lastPos;
121	        if (delta < 0) {
122	            // shiftForward(i, len, -delta);
123	            rect[xyDim] -= delta;
124	            item.label[xyDim] -= delta;
125	            adjusted = true;
126	        }
127	        const shift = Math.max(-delta, 0);
128	        shifts.push(shift);
129	        totalShifts += shift;
130	
131	        lastPos = rect[xyDim] + rect[sizeDim];
132	    }
133	    if (totalShifts > 0 && balanceShift) {
134	        // Shift back to make the distribution more equally.
135	        shiftList(-totalShifts / len, 0, len);
136	    }
137	
138	    // TODO bleedMargin?
139	    const first = list[0];
140	    const last = list[len - 1];
141	    let minGap: number;
142	    let maxGap: number;
143	    updateMinMaxGap();
144	
145	    // If ends exceed two bounds, squeeze at most 80%, then take the gap of two bounds.
146	    minGap < 0 && squeezeGaps(-minGap, 0.8);
147	    maxGap < 0 && squeezeGaps(maxGap, 0.8);
148	    updateMinMaxGap();
149	    takeBoundsGap(minGap, maxGap, 1);
150	    takeBoundsGap(maxGap, minGap, -1);
151	
152	    // Handle bailout when there is not enough space.
153	    updateMinMaxGap();
154	
155	    if (minGap < 0) {
156	        squeezeWhenBailout(-minGap);
157	    }
158	    if (maxGap < 0) {
159	        squeezeWhenBailout(maxGap);
160	    }
161	
162	    function updateMinMaxGap() {
163	        minGap = first.rect[xyDim] - minBound;
164	        maxGap = maxBound - last.rect[xyDim] - last.rect[sizeDim];
165	    }
166	
167	    function takeBoundsGap(gapThisBound: number, gapOtherBound: number, moveDir: 1 | -1) {
168	        if (gapThisBound < 0) {
169	            // Move from other gap if can.
170	            const moveFromMaxGap = Math.min(gapOtherBound, -gapThisBound);
171	            if (moveFromMaxGap > 0) {
172	                shiftList(moveFromMaxGap * moveDir, 0, len);
173	                const remained = moveFromMaxGap + gapThisBound;
174	                if (remained < 0) {
175	                    squeezeGaps(-remained * moveDir, 1);
176	                }
177	            }
178	            else {
179	                squeezeGaps(-gapThisBound * moveDir, 1);
180	            }
181	        }
182	    }
183	
184	    function shiftList(delta: number, start: number, end: number) {
185	        if (delta !== 0) {
186	            adjusted = true;
187	        }
188	        for (let i = start; i < end; i++) {
189	            const item = list[i];
190	            const rect = item.rect;
191	            rect[xyDim] += delta;
192	            item.label[xyDim] += delta;
193	        }
194	    }
195	
196	    // Squeeze gaps if the labels exceed margin.
197	    function squeezeGaps(delta: number, maxSqeezePercent: number) {
198	        const gaps: number[] = [];
199	        let totalGaps = 0;
200	        for (let i = 1; i < len; i++) {
201	            const prevItemRect = list[i - 1].rect;
202	            const gap = Math.max(list[i].rect[xyDim] - prevItemRect[xyDim] - prevItemRect[sizeDim], 0);
203	            gaps.push(gap);
204	            totalGaps += gap;
205	        }
206	        if (!totalGaps) {
207	            return;
208	        }
209	
210	        const squeezePercent = Math.min(Math.abs(delta) / totalGaps, maxSqeezePercent);
211	
212	        if (delta > 0) {
213	            for (let i = 0; i < len - 1; i++) {
214	                // Distribute the shift delta to all gaps.
215	                const movement = gaps[i] * squeezePercent;
216	                // Forward
217	                shiftList(movement, 0, i + 1);
218	            }
219	        }
220	        else {
221	            // Backward
222	            for (let i = len - 1; i > 0; i--) {
223	                // Distribute the shift delta to all gaps.
224	                const movement = gaps[i - 1] * squeezePercent;
225	                shiftList(-movement, i, len);
226	            }
227	        }
228	    }
229	
230	    /**
231	     * Squeeze to allow overlap if there is no more space available.
232	     * Let other overlapping strategy like hideOverlap do the job instead of keep exceeding the bounds.
233	     */
234	    function squeezeWhenBailout(delta: number) {
235	        const dir = delta < 0 ? -1 : 1;
236	        delta = Math.abs(delta);
237	        const moveForEachLabel = Math.ceil(delta / (len - 1));
238	
239	        for (let i = 0; i < len - 1; i++) {
240	            if (dir > 0) {
241	                // Forward
242	                shiftList(moveForEachLabel, 0, i + 1);
243	            }
244	            else {
245	                // Backward
246	                shiftList(-moveForEachLabel, len - i - 1, len);
247	            }
248	
249	            delta -= moveForEachLabel;
250	
251	            if (delta <= 0) {
252	                return;
253	            }
254	        }
255	    }
256	
257	    return adjusted;
258	}
