260	/**
261	 * Adjust labels on x direction to avoid overlap.
262	 */
263	export function shiftLayoutOnX(
264	    list: Pick<LabelLayoutInfo, 'rect' | 'label'>[],
265	    leftBound: number,
266	    rightBound: number,
267	    // If average the shifts on all labels and add them to 0
268	    // TODO: Not sure if should enable it.
269	    // Pros: The angle of lines will distribute more equally
270	    // Cons: In some layout. It may not what user wanted. like in pie. the label of last sector is usually changed unexpectedly.
271	    balanceShift?: boolean
272	): boolean {
273	    return shiftLayout(list, 'x', 'width', leftBound, rightBound, balanceShift);
274	}
275	
276	/**
277	 * Adjust labels on y direction to avoid overlap.
278	 */
279	export function shiftLayoutOnY(
280	    list: Pick<LabelLayoutInfo, 'rect' | 'label'>[],
281	    topBound: number,
282	    bottomBound: number,
283	    // If average the shifts on all labels and add them to 0
284	    balanceShift?: boolean
285	): boolean {
286	    return shiftLayout(list, 'y', 'height', topBound, bottomBound, balanceShift);
287	}
