289	export function hideOverlap(labelList: LabelLayoutInfo[]) {
290	    const displayedLabels: LabelLayoutInfo[] = [];
291	
292	    // TODO, render overflow visible first, put in the displayedLabels.
293	    labelList.sort(function (a, b) {
294	        return b.priority - a.priority;
295	    });
296	
297	    const globalRect = new BoundingRect(0, 0, 0, 0);
298	
299	    function hideEl(el: Element) {
300	        if (!el.ignore) {
301	            // Show on emphasis.
302	            const emphasisState = el.ensureState('emphasis');
303	            if (emphasisState.ignore == null) {
304	                emphasisState.ignore = false;
305	            }
306	        }
307	
308	        el.ignore = true;
309	    }
310	
311	    for (let i = 0; i < labelList.length; i++) {
312	        const labelItem = labelList[i];
313	        const isAxisAligned = labelItem.axisAligned;
314	        const localRect = labelItem.localRect;
315	        const transform = labelItem.transform;
316	        const label = labelItem.label;
317	        const labelLine = labelItem.labelLine;
318	        globalRect.copy(labelItem.rect);
319	        // Add a threshold because layout may be aligned precisely.
320	        globalRect.width -= 0.1;
321	        globalRect.height -= 0.1;
322	        globalRect.x += 0.05;
323	        globalRect.y += 0.05;
324	
325	        let obb = labelItem.obb;
326	        let overlapped = false;
327	        for (let j = 0; j < displayedLabels.length; j++) {
328	            const existsTextCfg = displayedLabels[j];
329	            // Fast rejection.
330	            if (!globalRect.intersect(existsTextCfg.rect)) {
331	                continue;
332	            }
333	
334	            if (isAxisAligned && existsTextCfg.axisAligned) {   // Is overlapped
335	                overlapped = true;
336	                break;
337	            }
338	
339	            if (!existsTextCfg.obb) { // If self is not axis aligned. But other is.
340	                existsTextCfg.obb = new OrientedBoundingRect(existsTextCfg.localRect, existsTextCfg.transform);
341	            }
342	
343	            if (!obb) { // If self is axis aligned. But other is not.
344	                obb = new OrientedBoundingRect(localRect, transform);
345	            }
346	
347	            if (obb.intersect(existsTextCfg.obb)) {
348	                overlapped = true;
349	                break;
350	            }
351	        }
352	
353	        // TODO Callback to determine if this overlap should be handled?
354	        if (overlapped) {
355	            hideEl(label);
356	            labelLine && hideEl(labelLine);
357	        }
358	        else {
359	            label.attr('ignore', labelItem.defaultAttr.ignore);
360	            labelLine && labelLine.attr('ignore', labelItem.defaultAttr.labelGuideIgnore);
361	
362	            displayedLabels.push(labelItem);
363	        }
364	    }
365	}

