import { createChart, removeChart } from '../test/ut/core/utHelper';

// Safeguard for upstream fix "fix(pie): fix some labels may not show" (#20070 / #20074).
// With dense pie labels + avoidLabelOverlap, recalculateX in pie labelLayout could
// compute sqrt of a negative number, producing NaN label x and silently hiding labels.
describe('pie-label-visibility', function () {

    function getOuterSeriesLabels(chart: ReturnType<typeof createChart>) {
        chart.getZr().refreshImmediately();
        const model = chart.getModel();
        const series = model.getSeriesByIndex(1);
        const data = series.getData();
        const labels: { name: any; ignore: boolean; x: number; y: number }[] = [];
        data.each(function (idx) {
            const sector = data.getItemGraphicEl(idx) as any;
            const label = sector.getTextContent();
            labels.push({
                name: data.getName(idx),
                ignore: !!label.ignore,
                x: label.x,
                y: label.y
            });
        });
        return labels;
    }

    function makeOption() {
        return {
            series: [
                {
                    name: 'Access From',
                    type: 'pie',
                    selectedMode: 'single',
                    radius: [0, '30%'],
                    label: {
                        position: 'inner',
                        fontSize: 14
                    },
                    labelLine: {
                        show: false
                    },
                    data: [
                        { value: 1548, name: 'Search Engine' },
                        { value: 775, name: 'Direct' },
                        { value: 679, name: 'Marketing', selected: true }
                    ]
                },
                {
                    name: 'Access From',
                    type: 'pie',
                    radius: ['45%', '60%'],
                    labelLine: {
                        length: 30
                    },
                    label: {
                        formatter: '{a|{a}}{abg|}\n{hr|}\n  {b|{b}: }{c}  {per|{d}%}  ',
                        backgroundColor: '#F6F8FC',
                        borderColor: '#8C8D8E',
                        borderWidth: 1,
                        borderRadius: 4,
                        rich: {
                            a: {
                                color: '#6E7079',
                                lineHeight: 22,
                                align: 'center'
                            },
                            hr: {
                                borderColor: '#8C8D8E',
                                width: '100%',
                                borderWidth: 1,
                                height: 0
                            },
                            b: {
                                color: '#4C5058',
                                fontSize: 14,
                                fontWeight: 'bold',
                                lineHeight: 33
                            },
                            per: {
                                color: '#fff',
                                backgroundColor: '#4C5058',
                                padding: [3, 4],
                                borderRadius: 4
                            }
                        }
                    },
                    data: [
                        { value: 11048, name: 'Baidu' },
                        { value: 1335, name: 'Direct' },
                        { value: 310, name: 'Email' },
                        { value: 251, name: 'Google' },
                        { value: 234, name: 'Union Ads' },
                        { value: 147, name: 'Bing' },
                        { value: 135, name: 'Video Ads' },
                        { value: 102, name: 'Others' },
                        { value: 335, name: 'Direct1' },
                        { value: 310, name: 'Email1' },
                        { value: 251, name: 'Google1' },
                        { value: 234, name: 'Union Ads1' },
                        { value: 147, name: 'Bing1' },
                        { value: 135, name: 'Video Ads1' },
                        { value: 102, name: 'Others1' }
                    ]
                }
            ]
        };
    }

    it('keeps dense pie labels visible with finite positions', function () {
        const chart = createChart({ width: 600, height: 400 });
        chart.setOption(makeOption() as any);
        const labels = getOuterSeriesLabels(chart);
        expect(labels.length).toBe(15);
        labels.forEach(function (l) {
            // A NaN position means the label would be force-hidden by the layout.
            expect(isNaN(l.x)).toBe(false);
            expect(isNaN(l.y)).toBe(false);
            expect(l.ignore).toBe(false);
        });
        removeChart(chart);
    });
});

